import openpyxl
path='/root/data/workbook.xlsx'
for data_only in (False, True):
    wb=openpyxl.load_workbook(path,data_only=data_only)
    ws=wb['Data']
    print('data_only', data_only)
    print('merged', list(ws.merged_cells.ranges))
    for r in range(1, 23):
        vals=[]
        for c in range(1,13):
            v=ws.cell(r,c).value
            if v is not None:
                vals.append(f'{ws.cell(r,c).coordinate}={v!r}')
        if vals:
            print(' | '.join(vals))
    print('row heights hidden 1-40')
    for r in range(1,41):
        dim=ws.row_dimensions[r]
        if dim.hidden or dim.height:
            print(r, 'hidden', dim.hidden, 'height', dim.height)
    wb.close()
